"Os de sistema e de rede. Os outros ficam em \"Ligar e desligar\", na página de cada assunto, como na TV.":"Του συστήματος και του δικτύου. Οι υπόλοιπες είναι στο «Ενεργοποίηση και απενεργοποίηση», στη σελίδα κάθε θέματος, όπως στην τηλεόραση.",
"Outros recursos":"Άλλες λειτουργίες",
"Painel no navegador, PIN, unidade de rede e o Claude pela internet":"Πίνακας στο πρόγραμμα περιήγησης, PIN, μονάδα δικτύου και Claude μέσω internet",
"Pastas da TV, pendrive, enviar e baixar":"Φάκελοι τηλεόρασης, USB στικ, μεταφόρτωση και λήψη",
"Protetor de tela, fotos, mural e desligar sozinha":"Προφύλαξη οθόνης, φωτογραφίες, πίνακας ανακοινώσεων και αυτόματο κλείσιμο",
"Rede, ferramentas, recursos e shell. Raramente precisa":"Δίκτυο, εργαλεία, λειτουργίες και shell. Σπάνια χρειάζεται",
"Tema, tamanho da letra, previsão do tempo e o que aparece na tela inicial":"Θέμα, μέγεθος κειμένου, πρόγνωση καιρού και τι εμφανίζεται στην αρχική οθόνη",
"Últimos acessos":"Πρόσφατη πρόσβαση",
"Vol +":"Ένταση +",
"Vol −":"Ένταση −",
"Página":"Σελίδα",
"Shell emprestado (Shizuku)":"Δανεικό shell (Shizuku)",
"Apps feitos para o Shizuku usam o shell do launcher sem instalar o Shizuku. Cada app pede na TV, com o PIN.":"Οι εφαρμογές για Shizuku χρησιμοποιούν το shell του launcher χωρίς εγκατάσταση του Shizuku. Κάθε εφαρμογή ζητά άδεια στην τηλεόραση, με το PIN.",
"Nenhum app instalado pede o Shizuku.":"Καμία εγκατεστημένη εφαρμογή δεν ζητά Shizuku.",
"Permitir o shell?":"Να επιτραπεί το shell;",
"Revogar":"Ανάκληση",
"Controle de dono emprestado (Dhizuku)":"Δανεικός έλεγχος κατόχου (Dhizuku)",
"Apps feitos para o Dhizuku usam o controle de dono do launcher. Cada app pede na TV, com o PIN. Nenhum consegue tirar o dono do launcher nem apagar a TV. Poder total deixa o app rodar como o launcher e ler os dados dele.":"Οι εφαρμογές για Dhizuku χρησιμοποιούν τον έλεγχο κατόχου του launcher. Κάθε εφαρμογή ζητά άδεια στην τηλεόραση, με το PIN. Καμία δεν μπορεί να αφαιρέσει τον launcher από κάτοχο ή να διαγράψει την τηλεόραση. Η πλήρης ισχύς επιτρέπει στην εφαρμογή να εκτελείται ως launcher και να διαβάζει τα δεδομένα του.",
"Ligado.":"Ενεργό.",
"Desligado.":"Απενεργοποιήθηκε.",
"Desligado na TV: Configurações › Sistema › Avançado › Emprestar poderes do sistema.":"Ανενεργό στην τηλεόραση: Ρυθμίσεις › Σύστημα › Για προχωρημένους › Δανεισμός δυνατοτήτων συστήματος.",
"Este aparelho ainda não confia no certificado. Siga os passos abaixo e volte para esta página: ela confere sozinha.":"Αυτή η συσκευή δεν εμπιστεύεται ακόμα το πιστοποιητικό. Ακολουθήστε τα παρακάτω βήματα και επιστρέψτε σε αυτή τη σελίδα: ελέγχει μόνη της.",
"Abrir o painel com cadeado":"Άνοιγμα του πίνακα με λουκέτο",
"Pronto! Este aparelho já confia no certificado.":"Έτοιμο! Αυτή η συσκευή εμπιστεύεται ήδη το πιστοποιητικό.",
"Você já está com cadeado. Pode instalar o painel como app (passo 3).":"Έχετε ήδη το λουκέτο. Μπορείτε να εγκαταστήσετε τον πίνακα ως εφαρμογή (βήμα 3).",
"Criar conector: URL do servidor MCP = o endereço; autenticação OAuth.":"Δημιουργία connector: URL διακομιστή MCP = η διεύθυνση· έλεγχος ταυτότητας OAuth.",
"Série (vazio = a última vista)":"Σειρά (κενό = η τελευταία που είδατε)",
"JSON inválido ou com tipo que a lista não conhece: {\"acoes\":[...]}.":"Μη έγκυρο JSON ή τύπος που η λίστα δεν γνωρίζει: {\"acoes\":[...]}.",
"Guardado na TV.":"Αποθηκεύτηκε στην τηλεόραση.",
"O app Shizuku está instalado nesta TV, então o launcher não entra no caminho dele. Desinstale-o para usar o do launcher.":"Η εφαρμογή Shizuku είναι εγκατεστημένη σε αυτή την τηλεόραση, οπότε ο launcher δεν την ενοχλεί. Απεγκαταστήστε την για να χρησιμοποιήσετε του launcher.",
"O launcher não é o dono desta TV: não há o que emprestar.":"Ο launcher δεν είναι ο κάτοχος αυτής της τηλεόρασης: δεν υπάρχει τίποτα για δανεισμό.",
"Nenhum app autorizado. O app pede na TV na primeira vez.":"Καμία εξουσιοδοτημένη εφαρμογή. Η εφαρμογή ζητά άδεια στην τηλεόραση την πρώτη φορά.",
" · poder total":" · πλήρης ισχύς",
" · só o controle de dono":" · μόνο έλεγχος κατόχου",
