" · sem acesso":" · χωρίς πρόσβαση",
" · estado só com o empréstimo rodando":" · κατάσταση μόνο όσο τρέχει ο δανεισμός",
"1. Toque em ":"1. Πατήστε ",
"Serviços de filmes e séries":"Υπηρεσίες ταινιών και σειρών",
"Contas opcionais: nada sai da TV antes de você entrar. Entrar e sair pedem o PIN.":"Προαιρετικοί λογαριασμοί: τίποτα δεν φεύγει από την τηλεόραση μέχρι να συνδεθείτε. Η σύνδεση και η αποσύνδεση ζητούν το PIN.",
"Deixa o que você viu e a sua lista iguais aos do celular.":"Κρατά συγχρονισμένα με το κινητό όσα είδατε και τη λίστα παρακολούθησης.",
"Igual ao Trakt, ótimo também para anime. Use um ou os dois.":"Όπως το Trakt, εξαιρετικό και για anime. Χρησιμοποιήστε το ένα ή και τα δύο.",
"Opcional: listas como o Top 250 viram categorias em Filmes e Séries.":"Προαιρετικό: λίστες όπως το Top 250 γίνονται κατηγορίες σε Ταινίες και Σειρές.",
"Opcional: suas listas do MDBList (como o Top 250) viram categorias em Filmes e Séries. 1. Abra":"Προαιρετικό: οι λίστες σας στο MDBList (όπως το Top 250) γίνονται κατηγορίες σε Ταινίες και Σειρές. 1. Ανοίξτε το",
"e entre (ou crie uma conta grátis). 2. No fim da página, toque em API Access, gere a chave se ainda não tiver e copie. 3. Cole aqui e grave: a TV confere na hora.":"και συνδεθείτε (ή δημιουργήστε δωρεάν λογαριασμό). 2. Στο κάτω μέρος της σελίδας, πατήστε API Access, δημιουργήστε το κλειδί αν δεν έχετε ακόμα και αντιγράψτε το. 3. Επικολλήστε το εδώ και αποθηκεύστε: η τηλεόραση το ελέγχει αμέσως.",
"Sinopse, elenco e data do próximo episódio, no idioma da TV.":"Υπόθεση, ηθοποιοί και ημερομηνία επόμενου επεισοδίου, στη γλώσσα της τηλεόρασης.",
"Legendas da internet. Sem conta: 5 por dia. Com conta grátis: 20.":"Υπότιτλοι online. Χωρίς λογαριασμό: 5 την ημέρα. Με δωρεάν λογαριασμό: 20.",
"Esta versão do launcher ainda não tem as chaves destes serviços. Eles aparecem depois da próxima atualização.":"Αυτή η έκδοση του launcher δεν έχει ακόμα τα κλειδιά αυτών των υπηρεσιών. Θα εμφανιστούν μετά την επόμενη ενημέρωση.",
