"Idade do modo infantil gravada. Filmes e séries com classificação até ela aparecem; os sem classificação, só nas categorias infantis.":"Η ηλικία της λειτουργίας παιδιών αποθηκεύτηκε. Εμφανίζονται ταινίες και σειρές με διαβάθμιση έως αυτήν· όσες δεν έχουν διαβάθμιση, μόνο σε παιδικές κατηγορίες.",
