"O que você marca aqui aparece lá e o de lá aparece aqui.":"Ό,τι σημειώνετε εδώ εμφανίζεται εκεί, και αντίστροφα.",
"Filmes e episódios vistos ficam marcados nos dois lados.":"Οι ταινίες και τα επεισόδια που είδατε σημειώνονται και στις δύο πλευρές.",
"Parou no celular? A TV continua do mesmo ponto, e o contrário.":"Σταματήσατε στο κινητό; Η τηλεόραση συνεχίζει από το ίδιο σημείο, και αντίστροφα.",
"A TV avisa o serviço enquanto você assiste. Nunca no Modo visita nem no perfil infantil.":"Η τηλεόραση ενημερώνει την υπηρεσία όσο βλέπετε. Ποτέ σε λειτουργία Επίσκεψης ή στο παιδικό προφίλ.",
