"As listas marcadas aparecem como categorias em Filmes e Séries.":"Οι επιλεγμένες λίστες εμφανίζονται ως κατηγορίες σε Ταινίες και Σειρές.",
"Listas gravadas.":"Οι λίστες αποθηκεύτηκαν.",
