"Gravar a chave do MDBList?":"Αποθήκευση του κλειδιού MDBList;",
"A TV confere a chave no MDBList antes de gravar.":"Η τηλεόραση ελέγχει το κλειδί με το MDBList πριν το αποθηκεύσει.",
