"\"Coloca o último episódio de Round 6 na Netflix.\"":"«Βάλε το τελευταίο επεισόδιο του Squid Game στο Netflix.»",
"\"Cria um despertador às 6:30 nos dias úteis.\"":"«Βάλε ξυπνητήρι στις 6:30 τις καθημερινές.»",
"\"Faz um checkup da TV e da internet.\"":"«Κάνε έλεγχο της τηλεόρασης και του internet.»",
"\"Instala este APK: https://...\" e \"Atualiza o launcher.\"":"«Εγκατάστησε αυτό το APK: https://...» και «Ενημέρωσε τον launcher.»",
"\"Manda um recado na TV: o jantar está pronto.\"":"«Στείλε μήνυμα στην τηλεόραση: το φαγητό είναι έτοιμο.»",
"\"O que está passando na TV?\" (precisa de \"Ver a tela pelo Claude\" ligado em Extras)":"«Τι παίζει στην τηλεόραση;» (χρειάζεται το «Το Claude βλέπει την οθόνη» ενεργό στα Extras)",
"\"Põe a TV para dormir.\" / \"Aumenta o volume.\"":"«Βάλε την τηλεόραση σε ύπνο.» / «Δυνάμωσε την ένταση.»",
"(o painel sem cadeado continua funcionando). Use isto se o certificado venceu, se o IP da TV mudou ou se um aparelho se perdeu.":"(ο πίνακας χωρίς λουκέτο συνεχίζει να λειτουργεί). Χρησιμοποιήστε το αν το πιστοποιητικό έληξε, άλλαξε η IP της τηλεόρασης ή μια συσκευή το έχασε.",
"+ Adicionar ação":"+ Προσθήκη ενέργειας",
", força":", ένταση",
", volume até":", ένταση έως",
