"5 min na tela":"5 λεπτά στην οθόνη",
"7 dias":"7 ημέρες",
": início":": έναρξη",
"A TV":"Η τηλεόραση",
"A TV ainda está gerando o certificado. Volte em 1 minuto.":"Η τηλεόραση δημιουργεί ακόμα το πιστοποιητικό. Επιστρέψτε σε 1 λεπτό.",
"A TV ainda não deu acesso às sessões de mídia (o shell do launcher precisa estar de pé).":"Η τηλεόραση δεν έχει ακόμα πρόσβαση στις περιόδους πολυμέσων (πρέπει να τρέχει το shell του launcher).",
"A TV avisa no celular: lembrete de jogo, alarme perdido, TV ligada de madrugada, erro, pedido de ajuda. Funciona com o painel aberto pelo endereço https (Tailscale, porta 8443) e o Chrome do Android. O aviso sai cifrado da TV.":"Η τηλεόραση ειδοποιεί το κινητό σας: υπενθύμιση αγώνα, ξυπνητήρι που χάθηκε, τηλεόραση ανοιχτή αργά τη νύχτα, σφάλμα, αίτημα βοήθειας. Λειτουργεί με τον πίνακα ανοιχτό στη διεύθυνση https (Tailscale, θύρα 8443) στο Chrome σε Android. Η ειδοποίηση φεύγει από την τηλεόραση κρυπτογραφημένη.",
"A TV desliga e liga de novo (cerca de 1 min). O painel volta sozinho depois.":"Η τηλεόραση κλείνει και ανοίγει ξανά (περίπου 1 λεπτό). Ο πίνακας επιστρέφει μόνος του.",
"A TV entra na sua rede Tailscale e publica só o MCP na internet.":"Η τηλεόραση μπαίνει στο δίκτυό σας Tailscale και δημοσιεύει στο internet μόνο το MCP.",
"A TV está sem conta Google (ou o launcher está sem a permissão de ver as contas).":"Η τηλεόραση δεν έχει λογαριασμό Google (ή ο launcher δεν βλέπει τους λογαριασμούς).",
"A TV fala direto com o Home Assistant da casa (sem nuvem): luzes e cenas aqui, na TV (Extras > Casa) e pelo Claude. Ela também aparece lá como sensor (ligada/dormindo, app aberto). O token fica cifrado na TV. Configurar pede o PIN.":"Η τηλεόραση μιλά απευθείας με το Home Assistant σας (χωρίς cloud): φώτα και σκηνές εδώ, στην τηλεόραση (Extras > Σπίτι) και μέσω Claude. Εμφανίζεται επίσης εκεί ως αισθητήρας (ανοιχτή/σε ύπνο, ανοιχτή εφαρμογή). Το token μένει κρυπτογραφημένο στην τηλεόραση. Η ρύθμιση ζητά το PIN.",
"A TV guarda sozinha uma cópia por dia (as últimas 7), só quando algo mudou. Baixe uma para restaurar em outra TV, ou volte esta TV para o estado daquele dia.":"Η τηλεόραση κρατά μόνη της ένα αντίγραφο την ημέρα (τα τελευταία 7), μόνο όταν κάτι άλλαξε. Κατεβάστε ένα για επαναφορά σε άλλη τηλεόραση ή επαναφέρετε αυτή την τηλεόραση σε εκείνη την ημέρα.",
"A TV ligou":"Η τηλεόραση άνοιξε",
"A TV manda cada linha nova das origens marcadas (POST com JSON) para este endereço: https, ou http só dentro de casa (ex.: um webhook do Home Assistant). Mudar pede o PIN. Vazio desliga.":"Η τηλεόραση στέλνει κάθε νέα γραμμή από τις επιλεγμένες πηγές (POST με JSON) σε αυτή τη διεύθυνση: https, ή http μόνο μέσα στο σπίτι (π.χ. webhook του Home Assistant). Η αλλαγή ζητά το PIN. Κενό την απενεργοποιεί.",
"A TV não criou a chave dos avisos. Tente de novo.":"Η τηλεόραση δεν δημιούργησε το κλειδί ειδοποιήσεων. Δοκιμάστε ξανά.",
"A TV não está no Wi-Fi (no cabo ou desconectada): nada a ajustar no Wi-Fi.":"Η τηλεόραση δεν είναι σε Wi-Fi (καλώδιο ή αποσυνδεδεμένη): τίποτα για ρύθμιση στο Wi-Fi.",
"A TV passa a responder pela internet (Tailscale Funnel). Quem entrar precisa do PIN.":"Η τηλεόραση αρχίζει να απαντά μέσω internet (Tailscale Funnel). Όποιος συνδέεται χρειάζεται το PIN.",
"A TV sai da rede Tailscale. Para voltar, cole uma chave nova.":"Η τηλεόραση φεύγει από το δίκτυο Tailscale. Για επιστροφή, επικολλήστε νέο κλειδί.",
"A TV só digita letras, números, espaço e . , @ _ -":"Η τηλεόραση πληκτρολογεί μόνο γράμματα, αριθμούς, κενό και . , @ _ -",
"A TV vai":"Η τηλεόραση θα",
"A TV vai chamar":"Η τηλεόραση θα καλέσει",
"A conexão com a TV caiu no meio do envio (rede, ou a TV recusou o arquivo).":"Η σύνδεση με την τηλεόραση έπεσε κατά τη μεταφόρτωση (δίκτυο, ή η τηλεόραση απέρριψε το αρχείο).",
"A foto da tela não chegou inteira. Tentando de novo…":"Το στιγμιότυπο δεν έφτασε ολόκληρο. Νέα προσπάθεια…",
"A imagem da bolinha do perfil, no alto da tela da TV. Escolha qualquer foto: a TV recorta um quadrado do meio e guarda só nela. JPG, PNG ou WebP, até 8 MB.":"Η εικόνα προφίλ στην κορυφή της οθόνης της τηλεόρασης. Επιλέξτε οποιαδήποτε φωτογραφία: η τηλεόραση κόβει ένα τετράγωνο από τη μέση και την κρατά μόνο στην τηλεόραση. JPG, PNG ή WebP, έως 8 MB.",
"A leitura está desligada.":"Η μέτρηση είναι ανενεργή.",
"A semana ainda não foi montada (domingo, 20h).":"Η εβδομάδα δεν έχει συγκεντρωθεί ακόμα (Κυριακή, 20:00).",
"A tela da TV está apagada: o recado aparece quando ela ligar.":"Η οθόνη της τηλεόρασης είναι σβηστή: το μήνυμα εμφανίζεται όταν ανάψει.",
"Abra o painel pelo endereço de sempre (o IP da TV ou tv:8080).":"Ανοίξτε τον πίνακα στη συνηθισμένη διεύθυνση (την IP της τηλεόρασης ή tv:8080).",
"Abrindo na TV.":"Άνοιγμα στην τηλεόραση.",
"Abrindo no YouTube da TV.":"Άνοιγμα στο YouTube στην τηλεόραση.",
