"Apaga a pasta e TUDO o que está dentro dela, na TV. Não tem volta.":"Διαγράφει τον φάκελο και ΟΛΑ όσα περιέχει, στην τηλεόραση. Δεν αναιρείται.",
"Apaga login, configurações e downloads do app, como se tivesse acabado de instalar. Não tem volta.":"Διαγράφει τη σύνδεση, τις ρυθμίσεις και τις λήψεις της εφαρμογής, σαν να μόλις εγκαταστάθηκε. Δεν αναιρείται.",
"Apaga o arquivo da TV. Não tem volta.":"Διαγράφει το αρχείο από την τηλεόραση. Δεν αναιρείται.",
"Apaga o endereço, a chave guardada, o certificado e a lista de aparelhos conhecidos.":"Διαγράφει τη διεύθυνση, το αποθηκευμένο κλειδί, το πιστοποιητικό και τη λίστα γνωστών συσκευών.",
