"No painel rápido da TV (segure VOLTAR), com a chave \"Mural da família no painel rápido\" ligada: lista de compras e até 3 recados fixos. Lá dá para marcar um recado como lido e apagar.":"Στον γρήγορο πίνακα της τηλεόρασης (κρατήστε ΠΙΣΩ), με τον διακόπτη «Οικογενειακός πίνακας στον γρήγορο πίνακα» ενεργό: λίστα αγορών και έως 3 καρφιτσωμένα μηνύματα. Εκεί μπορείτε να σημειώσετε ένα μήνυμα ως αναγνωσμένο και να το διαγράψετε.",
"Aniversários":"Γενέθλια",
"Rádios":"Ραδιόφωνο",
"Na TV: Ouvir › Rádio (rádios do mundo todo, do radio-browser.info). Aqui dá para colar o endereço de qualquer rádio (.mp3, .aac, .m3u8, .pls ou .m3u); ela vira favorita na TV.":"Στην τηλεόραση: Ακούω › Ραδιόφωνο (σταθμοί από όλο τον κόσμο, από το radio-browser.info). Εδώ μπορείτε να επικολλήσετε τη διεύθυνση οποιουδήποτε σταθμού (.mp3, .aac, .m3u8, .pls ή .m3u)· γίνεται αγαπημένος στην τηλεόραση.",
