"Nenhuma rádio favorita.":"Κανένας αγαπημένος σταθμός.",
"Rádio na TV.":"Ο σταθμός στάλθηκε στην τηλεόραση.",
"Sua TV no ano (em dezembro, no protetor)":"Η τηλεόρασή σας φέτος (τον Δεκέμβριο, στην προφύλαξη οθόνης)",
"Na véspera e no dia, a tela inicial mostra \"Hoje é aniversário de…\". Com o ano, mostra também a idade.":"Την προηγούμενη ημέρα και την ημέρα, η αρχική οθόνη δείχνει «Σήμερα έχει γενέθλια ο/η …». Με το έτος, δείχνει και την ηλικία.",
