"Aparelhos conectados":"Συνδεδεμένες συσκευές",
"Aperte OK no controle da TV para confirmar (ou Cancelar).":"Πατήστε OK στο τηλεχειριστήριο της τηλεόρασης για επιβεβαίωση (ή Άκυρο).",
"Apps abertos, baixados do GitHub oficial de cada projeto. Na 1ª instalação a TV guarda quem assinou; depois só aceita a mesma assinatura. Pede o PIN.":"Εφαρμογές ανοιχτού κώδικα, κατεβασμένες από το επίσημο GitHub κάθε έργου. Στην 1η εγκατάσταση η τηλεόραση θυμάται ποιος την υπέγραψε· μετά δέχεται μόνο την ίδια υπογραφή. Ζητά το PIN.",
"Apps da TV vão alcançar esses aparelhos pela rede Tailscale.":"Οι εφαρμογές της τηλεόρασης θα φτάνουν σε αυτές τις συσκευές μέσω του δικτύου Tailscale.",
