"Armado. Aperte os botões do controle...":"Σε αναμονή. Πατήστε τα κουμπιά του τηλεχειριστηρίου...",
"Armar teclas (2 min)":"Αναμονή πλήκτρων (2 λεπτά)",
"Arquivos":"Αρχεία",
"Arraste para mover · toque = OK · segure = voltar":"Σύρετε για κίνηση · πάτημα = OK · κράτημα = πίσω",
"As próximas cópias saem trancadas com esta senha. Anote-a: sem ela não dá para restaurar.":"Τα επόμενα αντίγραφα κλειδώνουν με αυτόν τον κωδικό. Σημειώστε τον: χωρίς αυτόν δεν γίνεται επαναφορά.",
"Atalhos de porta (servidor de mídia em outro lugar)":"Συντομεύσεις θυρών (διακομιστής πολυμέσων αλλού)",
"Atalhos salvos. O túnel reinicia em alguns segundos.":"Οι συντομεύσεις αποθηκεύτηκαν. Το τούνελ επανεκκινεί σε λίγα δευτερόλεπτα.",
"Atualizando rápido":"Γρήγορη ανανέωση",
"Atualizar":"Ενημέρωση",
"Atualização do sistema só de madrugada (3h às 5h)":"Ενημέρωση συστήματος μόνο τη νύχτα (3 έως 5 π.μ.)",
"Até 6 cards grandes no lugar da HOME (chave \"Tela fácil\"; desligar pede o PIN). Marque os apps; sem marcar, vão os mais usados.":"Έως 6 μεγάλες κάρτες αντί για το HOME (διακόπτης «Εύκολη οθόνη»· η απενεργοποίηση ζητά το PIN). Επιλέξτε τις εφαρμογές· αν καμία, μπαίνουν οι πιο χρησιμοποιημένες.",
