"CEP":"CEP (ταχ. κώδικας Βραζιλίας)",
"CEP (ex.: 14015-060)":"CEP (π.χ. 14015-060)",
"Cada \"aparelho:porta\" vira http://127.0.0.1:porta na TV: no Jellyfin, Emby ou Kodi, use esse endereço como servidor. Só com a rede Tailscale ligada. Na mesma rede de casa não precisa.":"Κάθε «συσκευή:θύρα» γίνεται http://127.0.0.1:θύρα στην τηλεόραση: στο Jellyfin, Emby ή Kodi, χρησιμοποιήστε αυτή τη διεύθυνση ως διακομιστή. Μόνο με το δίκτυο Tailscale ενεργό. Δεν χρειάζεται στο ίδιο οικιακό δίκτυο.",
"Cada evento roda no máximo uma vez a cada 20 s. Filmes de outros apps precisam do acesso às notificações (\"Tocando agora\").":"Κάθε συμβάν εκτελείται το πολύ μία φορά ανά 20 δ. Οι ταινίες από άλλες εφαρμογές χρειάζονται πρόσβαση στις ειδοποιήσεις («Παίζει τώρα»).",
"Cada letra vai direto para a TV":"Κάθε γράμμα πηγαίνει κατευθείαν στην τηλεόραση",
"Cadastrar":"Προσθήκη",
"Cadastrar a conta na TV?":"Προσθήκη του λογαριασμού στην τηλεόραση;",
"Cadastrar conta":"Προσθήκη λογαριασμού",
"Canal da TV":"Κανάλι TV",
"Cancelado na TV.":"Ακυρώθηκε στην τηλεόραση.",
"Cancelar":"Άκυρο",
"Cancelar seleção":"Ακύρωση επιλογής",
