"Casa não configurada":"Το σπίτι δεν έχει ρυθμιστεί",
"Cenas por link":"Σκηνές μέσω συνδέσμου",
"Certificado do roteador":"Πιστοποιητικό router",
"Certificado novo pronto. Instale de novo nos aparelhos (Passo a passo).":"Νέο πιστοποιητικό έτοιμο. Εγκαταστήστε το ξανά στις συσκευές (Βήμα προς βήμα).",
"Chave de API":"Κλειδί API",
"Chave guardada. O túnel sobe em alguns segundos.":"Το κλειδί αποθηκεύτηκε. Το τούνελ ανεβαίνει σε λίγα δευτερόλεπτα.",
"Chaves":"Διακόπτες",
"Cidade":"Πόλη",
"Cima":"Πάνω",
"Claude (claude.ai, app do celular ou do PC)":"Claude (claude.ai, εφαρμογή κινητού ή υπολογιστή)",
"Claude pela internet (MCP)":"Claude μέσω internet (MCP)",
"Claude, ChatGPT e outras IAs controlam a TV: controle remoto, abrir apps e links, instalar APK, despertadores, avisos, arquivos e shell. O que pede OK no controle segue as Confirmações. O login é este mesmo PIN, ou a conta Google, se ligada abaixo. O painel não fica na internet: só o MCP.":"Το Claude, το ChatGPT και άλλες AI ελέγχουν την τηλεόραση: τηλεχειριστήριο, άνοιγμα εφαρμογών και συνδέσμων, εγκατάσταση APK, ξυπνητήρια, μηνύματα, αρχεία και shell. Ό,τι χρειάζεται OK στο τηλεχειριστήριο ακολουθεί τις Επιβεβαιώσεις. Η σύνδεση γίνεται με αυτό το ίδιο PIN, ή με τον λογαριασμό Google, αν ενεργοποιηθεί παρακάτω. Ο πίνακας δεν είναι στο internet: μόνο το MCP.",
"Cole a chave inteira (começa com tskey-).":"Επικολλήστε ολόκληρο το κλειδί (αρχίζει με tskey-).",
"Cole no arquivo de servidores MCP (mcp.json) e entre com o PIN quando pedir.":"Επικολλήστε στο αρχείο διακομιστών MCP (mcp.json) και συνδεθείτε με το PIN όταν ζητηθεί.",
"Com a chave \"Presença\" ligada: se os celulares marcados saírem da rede por 15 min e ninguém mexer no controle, a TV apaga a tela e avisa no celular.":"Με τον διακόπτη «Παρουσία» ενεργό: αν τα επιλεγμένα κινητά φύγουν από το δίκτυο για 15 λεπτά και κανείς δεν αγγίξει το τηλεχειριστήριο, η τηλεόραση σβήνει την οθόνη και ειδοποιεί το κινητό σας.",
"Com a chave ligada, um link secreto recebe recados (POST com JSON) do Home Assistant, dos Atalhos do iPhone ou de apps feitos para o TvOverlay. Gerar um link novo invalida o anterior e pede o PIN. O link só aparece agora: guarde-o.":"Με τον διακόπτη ενεργό, ένας μυστικός σύνδεσμος δέχεται μηνύματα (POST με JSON) από το Home Assistant, τις Συντομεύσεις του iPhone ή εφαρμογές για TvOverlay. Η δημιουργία νέου συνδέσμου ακυρώνει τον προηγούμενο και ζητά το PIN. Ο σύνδεσμος εμφανίζεται μόνο τώρα: αποθηκεύστε τον.",
"Com a chave ligada: no horário abaixo, só abrem os apps da lista (os do sistema sempre abrem) e o volume não passa do teto. Salvar pede o PIN.":"Με τον διακόπτη ενεργό: τις παρακάτω ώρες, ανοίγουν μόνο οι εφαρμογές της λίστας (οι εφαρμογές συστήματος ανοίγουν πάντα) και η ένταση δεν ξεπερνά το όριο. Η αποθήκευση ζητά το PIN.",
"Com isto, o login do Claude (e dos outros apps) deixa de aceitar o PIN: só passa uma conta Google que esteja em algum perfil desta TV. Crie no Google Cloud um cliente OAuth do tipo \"TVs e dispositivos de entrada limitada\" e cole o id e o segredo aqui. Deixe o id vazio e salve para voltar ao PIN.":"Με αυτό, η σύνδεση του Claude (και άλλων εφαρμογών) σταματά να δέχεται το PIN: μπαίνει μόνο λογαριασμός Google που υπάρχει σε κάποιο προφίλ αυτής της τηλεόρασης. Στο Google Cloud, δημιουργήστε client OAuth τύπου «TVs and Limited Input devices» και επικολλήστε εδώ το id και το secret. Αφήστε το id κενό και αποθηκεύστε για επιστροφή στο PIN.",
"Com o certificado que a TV fez instalado no aparelho, o painel abre com cadeado e vira app no celular e no PC.":"Με το πιστοποιητικό της τηλεόρασης εγκατεστημένο στη συσκευή, ο πίνακας ανοίγει με λουκέτο και γίνεται εφαρμογή στο κινητό και στον υπολογιστή.",
"Com o Fundo do protetor em “Fotos e vídeos passando” (na TV: Configurações › Tela e energia), o protetor mostra estas fotos por trás do relógio. Ficam só na TV, numa pasta do launcher. JPG, PNG ou WebP, até 15 MB cada.":"Με το Φόντο προφύλαξης ρυθμισμένο σε «Φωτογραφίες και βίντεο που εναλλάσσονται» (στην τηλεόραση: Ρυθμίσεις › Οθόνη και ενέργεια), η προφύλαξη οθόνης δείχνει αυτές τις φωτογραφίες πίσω από το ρολόι. Μένουν μόνο στην τηλεόραση, σε φάκελο του launcher. JPG, PNG ή WebP, έως 15 MB η καθεμία.",
