"Depois desse tempo sem ninguém apertar o controle, a TV mostra um aviso por 60 s e desliga. Qualquer botão cancela. Assistir um filme sem tocar no controle também conta como \"sem uso\".":"Μετά από τόση ώρα χωρίς να πατήσει κανείς το τηλεχειριστήριο, η τηλεόραση δείχνει μια ειδοποίηση για 60 δ. και κλείνει. Οποιοδήποτε κουμπί ακυρώνει. Μια ταινία χωρίς άγγιγμα του τηλεχειριστηρίου μετρά κι αυτή ως «εκτός χρήσης».",
"Desenho da HOME nesta versão:":"Σχεδίαση HOME σε αυτή την έκδοση:",
"Desinstalar":"Απεγκατάσταση",
"Desligado: a TV só publica o MCP. Ligado: http://onetv-<nome da TV>:8080, ou com cadeado https://onetv-<nome da TV>.<sua rede>.ts.net:8443, abre este painel de qualquer aparelho da conta Tailscale, com o mesmo PIN, nunca pela internet aberta.":"Ανενεργό: η τηλεόραση δημοσιεύει μόνο το MCP. Ενεργό: το http://onetv-<όνομα TV>:8080, ή με λουκέτο το https://onetv-<όνομα TV>.<το δίκτυό σας>.ts.net:8443, ανοίγει αυτόν τον πίνακα από οποιαδήποτε συσκευή του λογαριασμού Tailscale, με το ίδιο PIN, ποτέ στο ανοιχτό internet.",
"Desligado: defina a senha primeiro.":"Ανενεργό: ορίστε πρώτα τον κωδικό.",
"Desligado: o login usa o PIN do painel.":"Ανενεργό: η σύνδεση χρησιμοποιεί το PIN του πίνακα.",
