"Qualquer projeto que publique o APK no GitHub Releases. A TV escolhe o arquivo da arquitetura dela.":"Οποιοδήποτε έργο δημοσιεύει το APK του στο GitHub Releases. Η τηλεόραση επιλέγει το αρχείο για την αρχιτεκτονική της.",
