"Recado na TV quando aparecer um aparelho nunca visto (confere a cada 5 min)":"Μήνυμα στην τηλεόραση όταν εμφανίζεται άγνωστη συσκευή (έλεγχος κάθε 5 λεπτά)",
"Recado na TV.":"Μήνυμα στην τηλεόραση.",
"Recado na tela":"Μήνυμα στην οθόνη",
