"Receber avisos aqui":"Λήψη ειδοποιήσεων εδώ",
"Reconectar a TV…":"Επανασύνδεση της τηλεόρασης…",
"Rede":"Δίκτυο",
"Rede Tailscale":"Δίκτυο Tailscale",
"Rede e conexões":"Δίκτυο και συνδέσεις",
"Refazer a limpeza de apps depois de atualizar o sistema":"Επανάληψη του καθαρισμού εφαρμογών μετά από ενημέρωση συστήματος",
"Reiniciando… o painel volta em cerca de 1 min.":"Επανεκκίνηση… ο πίνακας επιστρέφει σε περίπου 1 λεπτό.",
"Reiniciar TV":"Επανεκκίνηση τηλεόρασης",
"Reiniciar a TV?":"Επανεκκίνηση της τηλεόρασης;",
"Relatar no GitHub":"Αναφορά στο GitHub",
"Remove os apps e os dados deles. Não tem volta.":"Αφαιρεί τις εφαρμογές και τα δεδομένα τους. Δεν αναιρείται.",
"Renomear, mover ou apagar":"Μετονομασία, μετακίνηση ή διαγραφή",
