"Rodar uma cena quando algo acontecer":"Εκτέλεση σκηνής όταν συμβαίνει κάτι",
"Rode o comando abaixo e depois /mcp para fazer o login.":"Εκτελέστε την παρακάτω εντολή και μετά /mcp για σύνδεση.",
"Roteador":"Router",
"Roteador UniFi":"Router UniFi",
"Sair":"Αποσύνδεση",
