"Salvar apps":"Αποθήκευση εφαρμογών",
"Salvar atalhos":"Αποθήκευση συντομεύσεων",
"Salvar campainha":"Αποθήκευση κουδουνιού",
"Salvar com o mesmo nome substitui a cena e gera um link novo (o antigo para de funcionar).":"Η αποθήκευση με το ίδιο όνομα αντικαθιστά τη σκηνή και δημιουργεί νέο σύνδεσμο (ο παλιός σταματά να λειτουργεί).",
"Salvar endereço":"Αποθήκευση διεύθυνσης",
"Salvar escolha":"Αποθήκευση επιλογής",
"Salvar eventos":"Αποθήκευση συμβάντων",
"Salvar o horário, o teto do volume e os apps liberados":"Αποθήκευση ωρών, ορίου έντασης και επιτρεπόμενων εφαρμογών",
"Salvar os atalhos?":"Αποθήκευση των συντομεύσεων;",
"Salvar os eventos que rodam cenas?":"Αποθήκευση των συμβάντων που εκτελούν σκηνές;",
"Saúde":"Υγεία",
"Se esconder ou desinstalar:":"Αν κρυφτεί ή απεγκατασταθεί:",
"Seg a sex":"Δευ έως Παρ",
"Selecionar vários":"Πολλαπλή επιλογή",
"Sem apps marcados: vão os mais usados.":"Καμία επιλεγμένη εφαρμογή: μπαίνουν οι πιο χρησιμοποιημένες.",
"Sem resposta da TV.":"Καμία απάντηση από την τηλεόραση.",
"Sem roteador UniFi: use o Home Assistant (o app dele no celular informa se a pessoa está em casa) ou o IP fixo de cada celular (reserve o IP no roteador). Basta um deles dizer \"em casa\".":"Χωρίς router UniFi: χρησιμοποιήστε το Home Assistant (η εφαρμογή κινητού του ενημερώνει αν το άτομο είναι σπίτι) ή τη σταθερή IP κάθε κινητού (δεσμεύστε την IP στο router). Αρκεί ένα από αυτά να λέει «σπίτι».",
"Senha":"Κωδικός",
"Senha guardada. Guarde-a num lugar seguro.":"Ο κωδικός αποθηκεύτηκε. Φυλάξτε τον κάπου ασφαλές.",
"Sensor da campainha (ex.: binary_sensor.campainha)":"Αισθητήρας κουδουνιού (π.χ. binary_sensor.doorbell)",
"Servidores reserva":"Εφεδρικοί διακομιστές",
"Servidores reserva (opcional, separados por vírgula)":"Εφεδρικοί διακομιστές (προαιρετικό, χωρισμένοι με κόμμα)",
"Sessão expirada.":"Η συνεδρία έληξε.",
"Sessão expirada: entre de novo.":"Η συνεδρία έληξε: συνδεθείτε ξανά.",
"Seções do painel":"Ενότητες πίνακα",
"Sinal, banda e velocidade medidos pela própria TV; ponto de acesso, canal e retransmissões vêm do roteador. Nada é mudado no roteador: as dicas dizem o que ajustar no app do UniFi.":"Σήμα, ζώνη και ταχύτητα μετρημένα από την ίδια την τηλεόραση· σημείο πρόσβασης, κανάλι και επαναμεταδόσεις έρχονται από το router. Τίποτα δεν αλλάζει στο router: οι συμβουλές λένε τι να ρυθμίσετε στην εφαρμογή UniFi.",
"Sistema":"Σύστημα",
"Solte para enviar para":"Έκδοση για αποστολή",
"Clique ao navegar nas outras telas":"Κλικ κατά την κίνηση στις άλλες οθόνες",
"Somar":"Προσθήκη",
"Somar repositório":"Προσθήκη αποθετηρίου",
"Sua semana e desempenho":"Η εβδομάδα σας και η απόδοση",
"Retrospectiva da semana (domingo à noite)":"Εβδομαδιαία ανασκόπηση (Κυριακή βράδυ)",
"Subir uma pasta":"Έναν φάκελο πάνω",
"Substitui as configurações da TV pelas do arquivo e reinicia o launcher. O estado de antes fica guardado:":"Αντικαθιστά τις ρυθμίσεις της τηλεόρασης με αυτές του αρχείου και επανεκκινεί τον launcher. Η προηγούμενη κατάσταση φυλάσσεται:",
"Sábado":"Σάββατο",
"Símbolos que a TV não digita são pulados.":"Τα σύμβολα που η τηλεόραση δεν μπορεί να πληκτρολογήσει παραλείπονται.",
"Só instale APK de fonte confiável: o app pode pedir permissões.":"Εγκαθιστάτε APK μόνο από αξιόπιστες πηγές: η εφαρμογή μπορεί να ζητήσει δικαιώματα.",
"Só leitura: a TV vê os aparelhos conectados e se o roteador responde. Ela não bloqueia nem muda nada no roteador. A chave fica cifrada na TV e nunca volta para esta página (só os 4 últimos caracteres).":"Μόνο ανάγνωση: η τηλεόραση βλέπει τις συνδεδεμένες συσκευές και αν το router απαντά. Δεν μπλοκάρει ούτε αλλάζει τίποτα στο router. Το κλειδί μένει κρυπτογραφημένο στην τηλεόραση και δεν επιστρέφει ποτέ σε αυτή τη σελίδα (μόνο οι 4 τελευταίοι χαρακτήρες).",
