"Toda noite, com a TV parada, ela guarda um backup completo trancado com a senha abaixo (ficam as 7 últimas cópias) e, se quiser, uma cópia extra no pendrive ou numa pasta da rede. Anote a senha: sem ela as cópias não abrem. Trocar a senha ou a cópia extra pede o PIN de novo.":"Κάθε νύχτα, με την τηλεόραση αδρανή, κρατά πλήρες αντίγραφο κλειδωμένο με τον παρακάτω κωδικό (μένουν τα 7 τελευταία) και, αν θέλετε, επιπλέον αντίγραφο σε USB στικ ή φάκελο δικτύου. Σημειώστε τον κωδικό: χωρίς αυτόν τα αντίγραφα δεν ανοίγουν. Η αλλαγή του κωδικού ή του επιπλέον αντιγράφου ζητά ξανά το PIN.",
"Todos os apps →":"Όλες οι εφαρμογές →",
"Todos saíram (presença)":"Έφυγαν όλοι (παρουσία)",
"Token de longa duração":"Token μακράς διάρκειας",
"Touchpad: arraste para mover, toque para OK":"Touchpad: σύρετε για κίνηση, πατήστε για OK",
"Travar \"Forçar parada\" e \"Limpar dados\" do launcher e da VPN":"Κλείδωμα «Αναγκαστική διακοπή» και «Διαγραφή δεδομένων» του launcher και του VPN",
"Trocar":"Αλλαγή",
"Trocar a cópia extra?":"Αλλαγή του επιπλέον αντιγράφου;",
"Trocar foto…":"Αλλαγή φωτογραφίας…",
"Trocar o endereço apaga a chave e o certificado guardados (é preciso colar a chave de novo).":"Η αλλαγή της διεύθυνσης διαγράφει το αποθηκευμένο κλειδί και πιστοποιητικό (πρέπει να επικολλήσετε ξανά το κλειδί).",
"Tudo o que o backup acima leva e mais: contas de TV ao vivo, chave do UniFi, PIN do painel, controle parental, o Tailscale (a TV volta com o mesmo endereço) e os logins do Claude e dos outros apps no conector. Sai trancado com a senha abaixo: guarde-a, porque sem ela o arquivo não abre. Contas Google, Wi-Fi e logins de outros apps (Netflix, YouTube) o Android não deixa copiar.":"Ό,τι περιέχει το παραπάνω αντίγραφο και ακόμα περισσότερα: λογαριασμοί ζωντανής TV, κλειδί UniFi, PIN πίνακα, γονικός έλεγχος, Tailscale (η τηλεόραση επιστρέφει με την ίδια διεύθυνση) και οι συνδέσεις του Claude και των άλλων εφαρμογών στον connector. Βγαίνει κλειδωμένο με τον παρακάτω κωδικό: φυλάξτε τον, γιατί χωρίς αυτόν το αρχείο δεν ανοίγει. Το Android δεν επιτρέπει αντιγραφή λογαριασμών Google, Wi-Fi και συνδέσεων άλλων εφαρμογών (Netflix, YouTube).",
"Um app que não está na lista volta do login por um domínio dele (o \"redirect\" que ele mostra, ex.: app.exemplo.com). Libere o domínio aqui, sem esperar versão nova da TV. Pede o PIN, e a TV ainda pergunta \"cliente novo?\" no primeiro login.":"Μια εφαρμογή που δεν είναι στη λίστα επιστρέφει από τη σύνδεση μέσω δικού της τομέα (το «redirect» που δείχνει, π.χ. app.example.com). Επιτρέψτε τον τομέα εδώ, χωρίς να περιμένετε νέα έκδοση της τηλεόρασης. Ζητά το PIN, και η τηλεόραση ρωτά ακόμα «νέος client;» στην πρώτη σύνδεση.",
"Uma cena junta várias ações. Cada uma ganha um link secreto para os Atalhos do iPhone ou o Home Assistant (POST). O link só aparece ao criar: guarde-o. Criar e apagar pedem o PIN.":"Μια σκηνή ομαδοποιεί πολλές ενέργειες. Η καθεμία παίρνει μυστικό σύνδεσμο για Συντομεύσεις iPhone ή Home Assistant (POST). Ο σύνδεσμος εμφανίζεται μόνο κατά τη δημιουργία: αποθηκεύστε τον. Η δημιουργία και η διαγραφή ζητούν το PIN.",
"Usuário":"Χρήστης",
"Vai só o tipo do erro e o ponto do código onde ele aconteceu. A mensagem do erro, a rede, as contas e os apps ficam na TV. O GitHub abre com o texto pronto e você revisa antes de enviar.":"Στέλνεται μόνο ο τύπος σφάλματος και το σημείο του κώδικα όπου συνέβη. Το μήνυμα σφάλματος, το δίκτυο, οι λογαριασμοί και οι εφαρμογές μένουν στην τηλεόραση. Το GitHub ανοίγει με έτοιμο το κείμενο και το ελέγχετε πριν το στείλετε.",
