"Restaurar do Google Drive":"Επαναφορά από Google Drive",
"As cópias noturnas que estão no Drive. Restaurar pede a senha do backup e o PIN, substitui as configurações da TV e reinicia o launcher.":"Τα νυχτερινά αντίγραφα που είναι αποθηκευμένα στο Drive. Η επαναφορά ζητά τον κωδικό αντιγράφου και το PIN, αντικαθιστά τις ρυθμίσεις της τηλεόρασης και επανεκκινεί τον launcher.",
