"falta o login Google (aba Claude)":"λείπει η σύνδεση Google (καρτέλα Claude)",
"Conectar o Google Drive?":"Σύνδεση του Google Drive;",
"A TV pede um código ao Google. Depois, no celular, você entra com a conta Google da TV e digita o código. As cópias vão para a pasta OneTV-backup, trancadas com a senha do backup.":"Η τηλεόραση ζητά έναν κωδικό από τη Google. Μετά, στο κινητό σας, συνδέεστε με τον λογαριασμό Google της τηλεόρασης και πληκτρολογείτε τον κωδικό. Τα αντίγραφα πηγαίνουν στον φάκελο OneTV-backup, κλειδωμένα με τον κωδικό αντιγράφου.",
