"As mesmas opções das Configurações da TV: o que mudar aqui aparece lá, e o contrário também.":"Οι ίδιες επιλογές με τις Ρυθμίσεις της τηλεόρασης: ό,τι αλλάζετε εδώ εμφανίζεται εκεί, και αντίστροφα.",
