"Unidade de rede":"Μονάδα δικτύου",
"A memória da TV aparece no computador e no celular como uma pasta da rede (WebDAV), com as mesmas pastas da aba Arquivos. Senha: o PIN do painel (o usuário pode ser qualquer um, ex.: tv). Precisa do certificado da TV instalado no aparelho (":"Ο χώρος της τηλεόρασης εμφανίζεται στον υπολογιστή και στο κινητό σας ως φάκελος δικτύου (WebDAV), με τους ίδιους φακέλους με την καρτέλα Αρχεία. Κωδικός: το PIN του πίνακα (οποιοδήποτε όνομα χρήστη λειτουργεί, π.χ. tv). Η συσκευή χρειάζεται εγκατεστημένο το πιστοποιητικό της τηλεόρασης (",
"passo a passo":"βήμα προς βήμα",
"Mostrar a TV como unidade de rede":"Εμφάνιση της τηλεόρασης ως μονάδα δικτύου",
"No Windows, a TV aparece sozinha em Este Computador, como um celular, com as mesmas pastas da aba Arquivos. Na primeira vez de cada computador a TV pergunta na tela se pode. No Mac, Linux e celular ela é uma pasta da rede (WebDAV): senha = o PIN do painel, e precisa do certificado da TV (":"Στα Windows η τηλεόραση εμφανίζεται μόνη της στο «Αυτός ο υπολογιστής», σαν κινητό, με τους ίδιους φακέλους με την καρτέλα Αρχεία. Την πρώτη φορά για κάθε υπολογιστή η τηλεόραση ρωτά στην οθόνη. Σε Mac, Linux και κινητά είναι φάκελος δικτύου (WebDAV): κωδικός = το PIN του πίνακα, και χρειάζεται το πιστοποιητικό της τηλεόρασης (",
