"Cuidar de longe":"Φροντίδα από μακριά",
"Avisos no celular de quem cuida de quem mora com esta TV: pedido de ajuda (segurar uma tecla 3 s, com a foto da tela), lembrete não confirmado e TV que não ligou até a hora de costume. Desligado de fábrica: só liga quando quem mora aí aceitar na própria TV, pelo controle. Antes, instale o painel no celular de quem cuida e ligue \"Receber avisos aqui\" (cartão acima).":"Ειδοποιήσεις στο κινητό όποιου φροντίζει το άτομο που ζει με αυτή την τηλεόραση: αίτημα βοήθειας (κράτημα κουμπιού για 3 δ., με φωτογραφία της οθόνης), υπενθύμιση που δεν επιβεβαιώθηκε και τηλεόραση που δεν άνοιξε μέχρι τη συνηθισμένη ώρα. Ανενεργό από προεπιλογή: ενεργοποιείται μόνο όταν το άτομο που ζει εκεί συμφωνήσει στην ίδια την τηλεόραση, με το τηλεχειριστήριο. Πρώτα, εγκαταστήστε τον πίνακα στο κινητό του φροντιστή και ενεργοποιήστε το «Λήψη ειδοποιήσεων εδώ» (κάρτα παραπάνω).",
"Nome de quem recebe (ex.: Ana)":"Όνομα παραλήπτη (π.χ. Άννα)",
