"O texto do lembrete aparece grande na TV, com \"Feito\". Ele não sai da casa: o celular recebe só \"o lembrete das 20:00 não foi confirmado\".":"Το κείμενο της υπενθύμισης εμφανίζεται μεγάλο στην τηλεόραση, με «Έγινε». Δεν φεύγει από το σπίτι: το κινητό λαμβάνει μόνο «η υπενθύμιση των 20:00 δεν επιβεβαιώθηκε».",
"Pedido de ajuda":"Αίτημα βοήθειας",
"A tela da TV no momento do pedido":"Η οθόνη της τηλεόρασης τη στιγμή που ζητήθηκε βοήθεια",
"A foto é do momento do pedido (pode sair preta com filme protegido). A tela de agora e o controle estão logo abaixo.":"Η φωτογραφία είναι από τη στιγμή του αιτήματος (μπορεί να είναι μαύρη με προστατευμένη ταινία). Η τρέχουσα οθόνη και το τηλεχειριστήριο είναι ακριβώς από κάτω.",
