"Gravado. Para ligar, toque em \"Perguntar na TV\": quem mora aí aceita pelo controle.":"Αποθηκεύτηκε. Για ενεργοποίηση, πατήστε «Ερώτηση στην τηλεόραση»: το άτομο που ζει εκεί συμφωνεί με το τηλεχειριστήριο.",
"A pergunta está na TV. Só vale o aceite pelo controle da TV, não por este painel.":"Η ερώτηση είναι στην τηλεόραση. Μετρά μόνο η συμφωνία με το τηλεχειριστήριο της τηλεόρασης, όχι αυτός ο πίνακας.",
"Desligar o Cuidar de longe?":"Απενεργοποίηση της Φροντίδας από μακριά;",
"Os celulares recebem um último aviso dizendo que foi desligado. Para ligar de novo, a TV pergunta outra vez.":"Τα κινητά λαμβάνουν μια τελευταία ειδοποίηση ότι απενεργοποιήθηκε. Για νέα ενεργοποίηση, η τηλεόραση ρωτά ξανά.",
"Disponível no plano Ultra.":"Διαθέσιμο στο πρόγραμμα Ultra.",
