"Pronto, mas desligado: toque em \"Perguntar na TV\". Quem mora aí aceita pelo controle.":"Έτοιμο, αλλά ανενεργό: πατήστε «Ερώτηση στην τηλεόραση». Το άτομο που ζει εκεί συμφωνεί με το τηλεχειριστήριο.",
