"Addons":"Πρόσθετα",
"Catálogos e vídeos de addons no formato do Stremio. Só vídeo por link direto (HTTP): torrent e P2P são recusados. Instalar e remover pedem o PIN.":"Κατάλογοι και βίντεο από πρόσθετα μορφής Stremio. Μόνο άμεσοι σύνδεσμοι βίντεο (HTTP): torrent και P2P απορρίπτονται. Η εγκατάσταση και η αφαίρεση ζητούν το PIN.",
"Li e aceito: quem instala responde pelo conteúdo do addon":"Διάβασα και αποδέχομαι: όποιος εγκαθιστά είναι υπεύθυνος για το περιεχόμενο του πρόσθετου",
"Endereço do addon":"Διεύθυνση πρόσθετου",
