"Remover addon?":"Αφαίρεση πρόσθετου;",
"Instalar addon?":"Εγκατάσταση πρόσθετου;",
"Remover":"Αφαίρεση",
"Este addon usa torrent/P2P. A TV só aceita addons com vídeo por link direto (HTTP).":"Αυτό το πρόσθετο χρησιμοποιεί torrent/P2P. Η τηλεόραση δέχεται μόνο πρόσθετα με άμεσους συνδέσμους βίντεο (HTTP).",
"Addon marcado como conteúdo adulto: não é aceito.":"Πρόσθετο σημειωμένο ως περιεχόμενο ενηλίκων: δεν γίνεται δεκτό.",
"Este addon precisa ser configurado antes. Configure no site dele e cole o endereço que ele der.":"Αυτό το πρόσθετο πρέπει πρώτα να ρυθμιστεί. Ρυθμίστε το στον ιστότοπό του και επικολλήστε τη διεύθυνση που σας δίνει.",
"Este addon não oferece catálogo, ficha, vídeo ou legenda.":"Αυτό το πρόσθετο δεν προσφέρει κατάλογο, λεπτομέρειες, βίντεο ή υπότιτλους.",
"O endereço não tem um addon válido (manifest.json).":"Η διεύθυνση δεν έχει έγκυρο πρόσθετο (manifest.json).",
"Endereço inválido. Cole o link que termina em manifest.json.":"Μη έγκυρη διεύθυνση. Επικολλήστε τον σύνδεσμο που τελειώνει σε manifest.json.",
"Limite de addons atingido. Remova um para instalar outro.":"Συμπληρώθηκε το όριο πρόσθετων. Αφαιρέστε ένα για να εγκαταστήσετε άλλο.",
"O addon não respondeu. Confira o endereço e tente de novo.":"Το πρόσθετο δεν απάντησε. Ελέγξτε τη διεύθυνση και δοκιμάστε ξανά.",
"Aceite os termos para instalar.":"Αποδεχτείτε τους όρους για εγκατάσταση.",
"Addons são feitos por terceiros. A Sofaly não cria, não hospeda e não confere o que eles mostram. Quem instala um addon responde pelo conteúdo dele e por ter direito de assistir. A Sofaly só toca vídeo por link direto: fontes de torrent e P2P são ignoradas.":"Τα πρόσθετα φτιάχνονται από τρίτους. Το Sofaly δεν δημιουργεί, δεν φιλοξενεί και δεν ελέγχει τι δείχνουν. Όποιος εγκαθιστά ένα πρόσθετο είναι υπεύθυνος για το περιεχόμενό του και για το αν έχει δικαίωμα να το δει. Το Sofaly παίζει μόνο άμεσους συνδέσμους βίντεο: οι πηγές torrent και P2P αγνοούνται.",
"Ler QR":"Σάρωση QR",
"Fechar câmera":"Κλείσιμο κάμερας",
"Câmera lendo o QR do addon":"Η κάμερα διαβάζει το QR του πρόσθετου",
"Para ler QR, abra o painel pelo endereço https (porta 8444). No http o navegador não libera a câmera.":"Για σάρωση QR, ανοίξτε τον πίνακα στη διεύθυνση https (θύρα 8444). Μέσω http το πρόγραμμα περιήγησης δεν επιτρέπει την κάμερα.",
"Não consegui abrir a câmera. Confira se o navegador tem permissão para usá-la.":"Δεν ήταν δυνατό το άνοιγμα της κάμερας. Ελέγξτε ότι το πρόγραμμα περιήγησης έχει άδεια να τη χρησιμοποιεί.",
"QR lido. Confira o endereço e toque em Instalar.":"Το QR διαβάστηκε. Ελέγξτε τη διεύθυνση και πατήστε Εγκατάσταση.",
