"Escolha como a TV usa o pendrive. Como memória da TV, ele recebe os apps pesados. Formatar apaga o pendrive: copie antes pelo PC (Este Computador > a TV > Drive USB). Mover e formatar pedem o PIN.":"Επιλέξτε πώς χρησιμοποιεί η τηλεόραση το USB στικ. Ως χώρος τηλεόρασης παίρνει τις βαριές εφαρμογές. Η διαμόρφωση σβήνει το στικ: αντιγράψτε το πρώτα από τον υπολογιστή (Αυτός ο υπολογιστής > η τηλεόραση > USB στικ). Η μετακίνηση και η διαμόρφωση ζητούν το PIN.",
