"Tudo o que está nele será apagado. Como memória da TV, ele só funciona nesta TV. Se ele já tem apps, eles voltam para a TV antes.":"Όλα όσα περιέχει θα σβηστούν. Ως χώρος τηλεόρασης λειτουργεί μόνο σε αυτή την τηλεόραση. Αν έχει ήδη εφαρμογές, επιστρέφουν πρώτα στην τηλεόραση.",
"Apagar e formatar":"Διαγραφή και διαμόρφωση",
"Trazer para a TV?":"Επιστροφή στην τηλεόραση;",
"Levar para o pendrive?":"Μετακίνηση στο USB στικ;",
"Mover":"Μετακίνηση",
"no pendrive":"στο USB στικ",
"Tudo o que está nele será apagado. Como memória da TV, ele só funciona nesta TV e precisa ficar sempre ligado: se falhar ou for tirado, a TV pode não ligar até você desconectá-lo. Se ele já tem apps, eles voltam para a TV antes.":"Όλα όσα περιέχει θα σβηστούν. Ως χώρος τηλεόρασης λειτουργεί μόνο σε αυτή την τηλεόραση και πρέπει να μένει συνδεδεμένο: αν χαλάσει ή αφαιρεθεί, η τηλεόραση μπορεί να μην ξεκινά μέχρι να το αποσυνδέσετε. Αν έχει ήδη εφαρμογές, επιστρέφουν πρώτα στην τηλεόραση.",
"App grande: em pendrive lento a mudança pode passar de 10 minutos e já travou uma TV no meio. O app fecha enquanto é movido. Só continue com ninguém assistindo.":"Μεγάλη εφαρμογή: σε αργό στικ η μετακίνηση μπορεί να πάρει πάνω από 10 λεπτά και έχει κολλήσει τηλεόραση στη μέση. Η εφαρμογή κλείνει όσο μετακινείται. Συνεχίστε μόνο όταν δεν βλέπει κανείς.",
"Não deu: este pendrive grava devagar demais (menos de 10 MB/s) para virar memória da TV. Use como pendrive comum.":"Δεν έγινε: αυτό το στικ γράφει πολύ αργά (κάτω από 10 MB/s) για να γίνει χώρος τηλεόρασης. Χρησιμοποιήστε το ως κανονικό στικ.",
