"O conjunto vale para todos os ícones do Sofaly. Embaixo, troque um por um: a troca vence o conjunto.":"Το σετ ισχύει για κάθε εικονίδιο του Sofaly. Παρακάτω, αλλάξτε τα ένα-ένα: μια αλλαγή υπερισχύει του σετ.",
