"Ajuste aplicado na TV.":"Εφαρμόστηκε στην τηλεόραση.",
"Muda na hora na tela da TV. A letra nova é baixada do Google Fonts na primeira vez.":"Αλλάζει την οθόνη της τηλεόρασης αμέσως. Μια νέα γραμματοσειρά κατεβαίνει από το Google Fonts την πρώτη φορά.",
"Ajuste de aparência ou de configuração de outro app ou do sistema, feito pelo fabricante. Não tem tela nem código próprio.":"Ρύθμιση εμφάνισης ή ρυθμίσεων για άλλη εφαρμογή ή το σύστημα, από τον κατασκευαστή. Δεν έχει δική της οθόνη ή κώδικα.",
"Não economiza nada ocultar, e o que ele ajusta (rede, Wi-Fi, Configurações...) pode voltar ao padrão errado.":"Η απόκρυψή της δεν εξοικονομεί τίποτα, και ό,τι ρυθμίζει (δίκτυο, Wi-Fi, Ρυθμίσεις...) μπορεί να επιστρέψει σε λάθος προεπιλογή.",
"App instalado por você.":"Εφαρμογή που εγκαταστήσατε.",
"Ocultar ou desinstalar afeta só ele, a não ser que algum app abaixo dependa dele.":"Η απόκρυψη ή η απεγκατάσταση επηρεάζει μόνο αυτή την εφαρμογή, εκτός αν εξαρτάται από αυτήν μια εφαρμογή παρακάτω.",
