"Sem informação. Na dúvida, não oculte: apps do sistema sem tela costumam servir a outros.":"Καμία πληροφορία. Αν έχετε αμφιβολία, μην την κρύψετε: οι εφαρμογές συστήματος χωρίς οθόνη συνήθως εξυπηρετούν άλλες.",
